#!/usr/bin/env python3
"""Append the separate continuous-stream study, preserving historical explorer bytes."""
import argparse,ast,base64,copy,hashlib,html,json,pathlib,re,shutil
import tailcache12_predictor_verify as checks
ROOT=pathlib.Path(__file__).resolve().parents[1];BASE=ROOT/'docs/predictor'
START='<!-- TAILCACHE_PREDICTOR_START -->';END='<!-- TAILCACHE_PREDICTOR_END -->'
def strip(page):return re.sub(re.escape(START)+'.*?'+re.escape(END),'',page,flags=re.S)
def render(hosted=False):
 path=BASE/'predictor-data-20261118.json';raw=path.read_text();d=json.loads(raw);checks.verify(d);digest=hashlib.sha256(path.read_bytes()).hexdigest()
 if hosted:
  summary=copy.deepcopy(d);summary['curves'].pop('data');raw=json.dumps(summary,separators=(',',':'))
 assert '</script' not in raw.lower()
 tree=ast.parse((ROOT/'scripts/tailcache12_service_explorer.py').read_text());css=next(n.value.value for n in ast.walk(tree) if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='css' for t in n.targets))
 css=css.replace('service-followup','predictor-followup').replace('sf-','pf-');url='predictor-data.json' if hosted else ''
 warn={c:sum(bool(r['warnings']) for r in d['forks'] if r['cohort']==c) for c in d['cohortInputs']}
 primary=d['numerical']['validation']['all'];fresh=d['numerical']['confirmation']['all'];a=primary['M1']['99.9'];b=primary['M2']['99.9'];fa=fresh['M1']['99.9'];fb=fresh['M2']['99.9']
 body=f'''<section id="predictor-followup" data-package-url="{url}" data-package-sha="{digest}" aria-labelledby="pf-title"><p class="pf-muted">Prospective write-rate study · 18 November 2026 · 18 pilot + 30 primary + 12 fresh secondary research forks</p><h2 id="pf-title">A response reversal, with a variable boundary</h2><p>With a continuous operation stream, 4 KiB values and zero extra application ballast, Caffeine has lower response p99.9 at 0% writes and ordinary Chronicle is lower at 5%. All three primary pairs favor Chronicle at 0.5%, but the two fresh secondary pairs disagree there. This is a write-rate response reversal with an unresolved transition. The original service-pressure research question remains separate.</p><div class="pf-cards"><div><strong>The original forecast missed</strong><p>The frozen prediction put the reversal between 0.5% and 2% writes. All three primary pairs already favor Chronicle at 0.5%; fresh confirmation is mixed there. The original forecast and the later 0.5% replication prediction both failed.</p></div><div><strong>Direction is easier than magnitude</strong><p>M1 and the lower-total-GC rule both call all 15 primary p99.9 pair directions. That tie prevents claiming superior winner prediction for the residual equation.</p></div><div><strong>Queue drain helps, with limits</strong><p>Primary median absolute p99.9 error: M1 {a['medianAbsoluteNs']/1000:.1f} µs → M2 {b['medianAbsoluteNs']/1000:.1f} µs. Fresh secondary: {fa['medianAbsoluteNs']/1000:.1f} → {fb['medianAbsoluteNs']/1000:.1f} µs. The simple constant-quantile baseline beats M2 on Chronicle alone. Inspect both backends below.</p></div></div><p class="pf-note"><strong>Finite-window evidence, not a steady-state pass.</strong> The pilot still failed the declared occupancy-stability criterion after 120 seconds of warmup. All 60 research forks retain transient qualification; warning-bearing forks are included ({warn['qualification']}/18 pilot, {warn['validation']}/30 primary, {warn['confirmation']}/12 fresh). A separate compiler probe does not erase those warnings. Conditional models read each run’s observed GC intervals; they do not forecast future GC.</p><div class="pf-shortcuts"><button type="button" data-cohort="validation">Inspect primary prediction test</button><button type="button" data-cohort="confirmation">Inspect fresh confirmation</button><button type="button" data-cohort="qualification">Inspect warmup development</button></div><div id="pf-chart-anchor"></div><div class="pf-controls"><label>Evidence cohort<select id="pf-cohort"></select></label><label>Frozen treatment<select id="pf-stage"></select></label><label>Latency channel<select id="pf-metric"></select></label><label>Percentile<select id="pf-q"><option>99</option><option selected>99.9</option><option>99.99</option><option>99.999</option></select></label></div><p id="pf-scope" class="pf-muted" aria-live="polite"></p><div id="pf-ratio" class="pf-scroll"></div><p class="pf-muted">Below 1 favors Chronicle; above 1 favors Caffeine. Each dot is a paired fork, red outline means a recorded warning. Labels keep seed and warmup explicit. No fitted threshold or pooled percentile.</p><div id="pf-table" class="pf-scroll"></div><h3 id="pf-detail-title">Selected point</h3><label>Retained pair<select id="pf-block"></select></label><div id="pf-detail"></div><h3>Conditional response reconstruction</h3><label>Model / comparator<select id="pf-model"><option value="M1">M1 · residual pause + baseline</option><option value="M2" selected>M2 · FIFO queue drain</option><option value="constant">Constant pilot quantile</option></select></label><div id="pf-prediction" class="pf-scroll"></div><div id="pf-errors" class="pf-scroll"></div><div id="pf-model-detail" class="pf-scroll"></div><button id="pf-load-tail" type="button">Load selected pair’s full tail</button><div id="pf-tail" class="pf-scroll"><p class="pf-muted">Separate empirical curves and strict stall-rate bounds for the selected channel.</p></div><div id="pf-rates" class="pf-scroll"></div><p id="pf-tail-note" class="pf-muted"></p><details><summary>Conclusions at every data point</summary><p>All 30 point groups remain separate by cohort, seed, write rate and warmup. Changing the percentile updates this table. Response p99.9 remains the primary endpoint; p99.999 has about 15 nominal upper-tail observations per fork.</p><div id="pf-all-table" class="pf-scroll"></div></details><details><summary>Definitions and what the model can claim</summary><dl class="pf-glossary"><dt>Write rate / basis points</dt><dd>0.5% means approximately one update per 200 operations; 50 basis points. Actual Bernoulli-selected write counts are checked between paired arms.</dd><dt>Continuous stream</dt><dd>Operation indices increase across warmup, conditioning and measurement. Keys naturally repeat, but no finite trace array is replayed. The new generator also costs CPU time; this is not an isolated lifetime intervention.</dd><dt>Scheduled response / service</dt><dd>Response ends at completion and starts at intended arrival, including waiting and queue debt. Service starts at the actual call. These paced service values do not replace separate saturated-service experiments.</dd><dt>Pause budget</dt><dd>In an ideal residual-pause model, p99.9’s upper 0.1% is 30 ms of a 30-second window. p99.99’s budget is 3 ms. Individual pause lengths determine the excess quantile. Baseline work, queue drain and non-GC stalls can change actual response.</dd><dt>M0, M1 and M2</dt><dd>M0 solves a clipped pause-only residual equation. M1 keeps actual pause ends and adds fixed historical timer/service allowances. M2 simulates a serial FIFO queue with pilot-derived constant service and bookkeeping plus the timer allowance. Neither additive quantiles nor constant work is exact.</dd><dt>Forecast versus conditional reconstruction</dt><dd>The original write-rate forecast was frozen before new data and failed at 0.5%. Conditional quantiles use a completed fork’s GC log: they explain new outcomes given observed pauses, rather than forecast future pauses or guarantee a crossover.</dd><dt>Transient qualification and warnings</dt><dd>Post-GC occupancy still changed beyond the declared tolerance after long warmup. All results keep that limit. Warning-free only means no additional recorded warning; it does not prove steady state.</dd><dt>Constant baseline / holdout</dt><dd>A fixed per-backend response quantile from the three long-warmup pilot cells is a simple numerical comparator. It was declared after the primary results, before fresh confirmation. Pilot, primary and secondary holdout are different evidence roles.</dd><dt>Extreme-tail support</dt><dd>1.5 million responses leave about 15 nominal observations above p99.999. Those can come from the same pause, so they are not 15 independent experiments. Bin bounds address quantization, not sampling confidence.</dd></dl></details><details><summary>Four scientific figures</summary>'''
 parts=[START,css,body];manifest=json.loads((BASE/'render-manifest-20261118.json').read_text())
 for i,r in enumerate(json.loads((BASE/'figure-index-20261118.json').read_text()),1):
  file=BASE/'figures'/(r['id']+'.png');assert hashlib.sha256(file.read_bytes()).hexdigest()==manifest['outputs']['figures/'+file.name]
  src='predictor-figures/'+file.name if hosted else 'data:image/png;base64,'+base64.b64encode(file.read_bytes()).decode()
  parts.append(f'<figure><img loading="lazy" src="{src}" alt="{html.escape(r["title"])}"><figcaption><strong>Figure B{i}.</strong> {html.escape(r["caption"])}</figcaption></figure>')
 parts.append('</details><div class="pf-links"><a id="pf-download" class="pf-link" href="'+(url or '#')+'" download="tailcache-predictor-20261118.json">Download verified predictor data</a><a class="pf-link" href="https://github.com/Enixes/TailCache/blob/codex/tailcache-preprint/docs/predictor/RESULTS.md">Methods, conclusions and limitations</a><a class="pf-link" href="https://github.com/Enixes/TailCache/pull/10">Review working manuscript</a></div></section>')
 parts+=['<script id="pf-data" type="application/json">'+raw+'</script>','<script>'+(ROOT/'scripts/tailcache12_predictor_ui.js').read_text()+'</script>',END]
 return ''.join(parts)
def refresh_downloads(page):
 for path in (ROOT/'docs/preprint/MANUSCRIPT.md',ROOT/'docs/TAILCACHE_CURRENT_STATE.md'):
  content=path.read_bytes();digest=hashlib.sha256(content).hexdigest();encoded=base64.b64encode(content).decode()
  pattern=r'<a\b[^>]*download="'+re.escape(path.name)+r'"[^>]*>.*?</a>'
  def update(match):
   tag=match[0];tag=re.sub(r'href="[^"]*"','href="data:text/markdown;base64,'+encoded+'"',tag)
   return re.sub(r'data-sha256="[^"]*"','data-sha256="'+digest+'"',tag)
  page=re.sub(pattern,update,page,flags=re.S)
 return page

def attach(page,component):
 old=refresh_downloads(strip(page));marker='<main class="wrap">'
 return old.replace(marker,marker+component,1) if marker in old else re.sub(r'(<body[^>]*>)',lambda m:m[0]+component,old,count=1)

def main():
 p=argparse.ArgumentParser();p.add_argument('--site-out',type=pathlib.Path);a=p.parse_args();offline=render()
 for name in ('TAILCACHE_RESULTS_EXPLORER.html','TAILCACHE_MIDPOINT_EXPLORER.html'):
  path=ROOT/'docs'/name;before=path.read_text();after=attach(before,offline);assert strip(after)==refresh_downloads(strip(before));path.write_text(after)
 if a.site_out:
  target=a.site_out/'index.html';before=target.read_text();target.write_text(attach(before,render(True)));assert strip(target.read_text())==refresh_downloads(strip(before))
  shutil.copyfile(BASE/'predictor-data-20261118.json',a.site_out/'predictor-data.json');shutil.copytree(BASE/'figures',a.site_out/'predictor-figures',dirs_exist_ok=True)
 print(json.dumps({'site':str(a.site_out),'historicalContentPreserved':True}))
if __name__=='__main__':main()
